import ast

errors = []
for i in range(len(value["MaxDiffGradient"])):
    if float(value["MaxDiffGradient"][i]) < 250:
        errors.append("Entry " + str(i) + ": MaxDiffGradient too low for axon diameter mapping")
    if float(value["NumberOfDiffusionShells"][i]) < 2:
        errors.append("Entry " + str(i) + ": NumberOfDiffusionShells too low for axon diameter mapping")
    bvals = as_list(value["DiffusionBValues"][i])
    if len([b for b in bvals if 0 < b < 1000]) == 0:
        errors.append("Entry " + str(i) + ": no non-zero b-value below 1000 s/mm2 present")

if errors:
    raise ValidationError(chr(10).join(errors))

